    auto size=uint64_t(end-start)*2;require(size+44<=maxSampleBytes,"SF2 sample too large");auto data=std::make_shared<Blob>();auto& b=*data;tag(b,"RIFF");add32(b,uint32_t(size+36));tag(b,"WAVE");tag(b,"fmt ");add32(b,16);add16(b,1);add16(b,1);add32(b,rate);add32(b,rate*2);add16(b,2);add16(b,16);tag(b,"data");add32(b,uint32_t(size));append(b,s.read(s.pcm.pos+uint64_t(start)*2,size_t(size)));
